const { useState, useEffect } = React;

function useFetch(url) {
  const [status, setStatus] = useState('loading');
  const [data, setData] = useState(null);

  useEffect(() => {
    let ignore = false;
    setStatus('loading');

    fetch(url)
      .then((res) => {
        if (!res.ok) throw new Error('실패');
        return res.json();
      })
      .then((body) => {
        if (ignore) return;
        setData(body);
        setStatus('ok');
      })
      .catch(() => {
        if (ignore) return;
        setStatus('error');
      });

    return () => {
      ignore = true;
    };
  }, [url]);

  return null /* ← 여기를 채우세요 */;
}

function Search({ query }) {
  const { status, data } = useFetch('/api/search?q=' + encodeURIComponent(query));

  if (status === 'loading') return <p className="state">찾는 중…</p>;
  if (status === 'error') return <p className="state">찾지 못했습니다</p>;

  return (
    <div>
      <p className="state">{query} · {data.length}개</p>
      {data.map((c) => <p className="course" key={c.id}>{c.name}</p>)}
    </div>
  );
}

// 아래 넷은 그대로 두세요. 검사기가 race 를 부릅니다
const root = ReactDOM.createRoot(document.querySelector('#root'));

const yieldTask = () => new Promise((done) => {
  const channel = new MessageChannel();
  channel.port1.onmessage = () => done();
  channel.port2.postMessage(0);
});

function waitQuiet() {
  const el = document.querySelector('#root');
  return new Promise((resolve) => {
    const startedAt = Date.now();
    let last = null;
    let same = 0;
    let tries = 0;
    const tick = () => {
      const now = el.textContent;
      same = now === last ? same + 1 : 0;
      last = now;
      tries += 1;
      // 늦게 오는 응답이 400ms 뒤에 옵니다. 그 전에 확정하면 낡은 응답을 보지 못합니다
      const quiet = same >= 2 && !now.includes('찾는 중') && Date.now() - startedAt > 600;
      if (quiet || tries > 40) resolve(now);
      else setTimeout(tick, 50);
    };
    tick();
  });
}

async function race(first, second) {
  root.render(<Search query={first} />);
  await yieldTask();
  await yieldTask();
  await yieldTask();
  root.render(<Search query={second} />);
  return waitQuiet();
}

